import { setActionFeedback } from './action-feedback.js';

// Reuse the lobby's Low Stakes quote and purchase owner, including its wallet,
// funds, duplicate-entry, and transaction guards.
export function mountCrapsQuickEntry(host) {
  const countdown=document.createElement('span');countdown.className='site-craps-countdown';
  const button=document.createElement('button');button.type='button';button.className='site-craps-buy';button.disabled=true;
  const feedback=document.createElement('div');feedback.setAttribute('role','status');feedback.hidden=true;document.body.append(feedback);
  host.append(countdown,button);
  let busy=false,selected=null;
  const options=()=>{const detail={};document.dispatchEvent(new CustomEvent('quest:craps-options',{detail}));return detail;};
  const paint=()=>{
    const data=options();selected=data.battles?.[0]?{...data.battles[0]}:null;
    const eventName=/^(Jackpot Battle|Main Event)$/i.test(selected?.label||'')?'MAIN EVENT':'NEXT BATTLE';
    const text=selected?`${eventName} IN ${selected.closes.replace(/^Closes in /,'')}`:data.battleStatus==='closed'?'BATTLES CLOSED':'BATTLE LOADING';
    if(countdown.textContent!==text)countdown.textContent=text;
    let label='ENTER · — FLIP';
    if(selected?.price!=null)label=`ENTER · ${BigInt(selected.price).toLocaleString('en-US')} FLIP`;
    if(selected?.entered)label='ENTERED';
    if(busy)label='ENTERING…';
    if(button.textContent!==label)button.textContent=label;
    button.disabled=busy||!selected?.joinable;
    button.title=selected?.disabledReason||data.battleMessage||'Enter the next Low Stakes battle with your current Craps chip board';
    button.setAttribute('aria-label',`${label}${selected?` · ${selected.label} · Low Stakes`:''}`);
  };
  button.addEventListener('click',async()=>{
    if(busy)return;
    const previous=selected;paint();
    if(!selected?.joinable)return;
    if(previous?.day!==selected.day||previous?.period!==selected.period||previous?.price!==selected.price){
      setActionFeedback(feedback,'The battle or price changed. Check the updated buy-in and try again.');return;
    }
    const detail={questType:10,submit:true,crapsTargetDay:selected.day,crapsPeriod:selected.period};
    busy=true;paint();setActionFeedback(feedback,'');
    try{
      document.dispatchEvent(new CustomEvent('quest:activate',{detail}));
      if(!detail.crapsHandled||!detail.crapsPurchase)throw Error('Craps is still loading. Try again.');
      const result=await detail.crapsPurchase;
      setActionFeedback(feedback,result?.ok?'Entered the battle.':result?.message||'Entry was not completed.');
    }catch(error){setActionFeedback(feedback,error?.message||'Entry was not completed.');}
    finally{busy=false;paint();}
  });
  document.addEventListener('craps:lobby-updated',paint);
  const refresh=async()=>{if(document.hidden||!matchMedia('(min-width:1100px)').matches)return;try{await document.querySelector('app-craps-entry')?.refreshQuestOptions?.();}catch{}paint();};
  paint();
  import('/app/components/app-craps-entry.js').then(refresh).catch(()=>{countdown.textContent='BATTLE UNAVAILABLE';});
  setInterval(()=>{if(!document.hidden)paint();},1000);
  setInterval(refresh,30000);
}
